INSERT INTO local_seo_pages (slug,page_type,title,seo_title,seo_description,excerpt,area_name,area_terms,center,radius_m,category_slug,map_region_slug,map_supported,body,status) VALUES
('phong-tro-quanh-dai-hoc-fpt','CAMPUS_RADIUS','Phòng trọ và nhà thuê quanh Đại học FPT Hòa Lạc','Phòng trọ và nhà thuê quanh Đại học FPT Hòa Lạc','Tìm phòng trọ và nhà thuê quanh Đại học FPT Hòa Lạc theo giá, diện tích, tình trạng còn phòng và vị trí thực tế.','Xem các lựa chọn thuê còn hiệu lực trong phạm vi tìm kiếm quanh Đại học FPT. So sánh tổng chi phí, loại phòng và đường đi trước khi đặt lịch.','Đại học FPT Hòa Lạc',ARRAY['Đại học FPT','Trường Đại học FPT','Khu Giáo dục và Đào tạo'],ST_SetSRID(ST_MakePoint(105.52522,21.01354),4326),3000,'bat-dong-san','hoa-lac',TRUE,'[{"heading":"Tính tổng chi phí trước khi đi xem","paragraphs":["Hãy xác định số người ở, ngân sách tối đa mỗi tháng và thời gian dự định thuê. Khi so sánh hai phòng, không nên chỉ nhìn số tiền thuê trên tiêu đề. Tiền điện, nước, gửi xe, internet và những khoản dịch vụ có thể làm tổng chi phí thực tế khác với mức giá được quảng cáo.","Trao đổi rõ tiền cọc, lịch thanh toán, thời hạn hợp đồng và điều kiện hoàn tiền. Yêu cầu chủ nhà giải thích từng khoản trước khi chuyển tiền. Nếu một thông tin chưa được cung cấp trong hồ sơ, hãy hỏi lại thay vì mặc định miễn phí."]},{"heading":"Kiểm tra từng loại phòng và đường đi","paragraphs":["Một tòa nhà có thể có nhiều loại phòng, diện tích, giá thuê và số phòng còn trống khác nhau. Chọn loại phù hợp với nhu cầu ở thực tế rồi xác nhận đúng phòng cần xem, tình trạng nội thất và ngày có thể chuyển vào. Không suy luận rằng ảnh của một phòng đại diện cho toàn bộ tòa nhà.","Sử dụng bản đồ để so sánh vị trí ghim với nơi học tập hoặc làm việc. Khoảng cách đường thẳng và quãng đường di chuyển không nhất thiết giống nhau. Kiểm tra tuyến đường thường dùng, thời gian đi lại, ánh sáng buổi tối và khả năng gửi xe."]},{"heading":"Đi xem trực tiếp và xác minh thông tin","paragraphs":["Khi xem nhà, kiểm tra cửa, khóa, điện, nước, vệ sinh, lối thoát hiểm và thông gió. Đối chiếu tên người cho thuê, quyền cho thuê và hợp đồng với thông tin được cung cấp; nếu có người môi giới, hãy làm rõ trách nhiệm và các khoản phí trước khi giao dịch.","HOLA Maps không tự xác minh quyền sở hữu nhà đất chỉ dựa trên tin đăng. Các hồ sơ phòng trọ thay đổi theo thời gian; hãy xem ngày xác nhận gần nhất và báo cáo khi giá, vị trí hoặc số phòng trống có dấu hiệu không đúng. Danh sách chỉ được xuất bản khi có đủ dữ liệu thực, ảnh, địa chỉ, tọa độ và xác minh mới theo cổng chất lượng."]}]'::jsonb,'DRAFT'),
('phong-tro-quanh-dai-hoc-quoc-gia','CAMPUS_RADIUS','Phòng trọ và nhà thuê quanh Đại học Quốc gia Hà Nội','Phòng trọ và nhà thuê quanh Đại học Quốc gia Hà Nội','Cẩm nang chọn phòng trọ, nhà thuê theo vị trí học tập, chi phí và tình trạng còn phòng quanh Đại học Quốc gia Hà Nội.','Chọn chỗ ở phù hợp với cơ sở học tập, ngân sách và đường đi thực tế. Danh sách chỉ xuất bản sau khi mốc trường và dữ liệu thuê được xác nhận.','Đại học Quốc gia Hà Nội',ARRAY['Đại học Quốc gia Hà Nội','ĐHQGHN'],NULL,3000,'bat-dong-san',NULL,FALSE,'[{"heading":"Làm rõ cơ sở học tập trước khi chọn chỗ ở","paragraphs":["Nếu học hoặc làm việc tại khu Đại học Quốc gia Hà Nội, hãy xác nhận đúng đơn vị, tòa nhà và thời điểm cần có mặt. Các điểm đến có thể nằm ở những vị trí khác nhau trong một khu vực rộng. Chọn chỗ ở chỉ theo tên trường có thể khiến việc di chuyển hằng ngày không thuận tiện.","Tạo danh sách những tiêu chí cần thiết như thời gian đi lại, khả năng gửi xe, không gian học tập và ngân sách hàng tháng. Dùng những tiêu chí này để so sánh từng hồ sơ thuê đang còn hiệu lực."]},{"heading":"So sánh chi phí sinh hoạt và điều kiện thuê","paragraphs":["Trước khi đặt lịch xem nhà, hãy xác định mức tiền thuê tối đa, khoản cọc có thể chi trả và các khoản dịch vụ bắt buộc. Yêu cầu người đăng cung cấp điều kiện sử dụng điện, nước, internet và phí gửi xe bằng văn bản nếu có thể. Giá ghi trong tin chưa chắc đã bao gồm toàn bộ các khoản này.","Kiểm tra diện tích sử dụng thực tế, nội thất, giờ giấc, số người ở tối đa và thời gian được chuyển vào. Nếu ở cùng người khác, hãy thống nhất việc chia chi phí và trách nhiệm khi kết thúc hợp đồng."]},{"heading":"Sử dụng vị trí đã được kiểm tra","paragraphs":["Mốc tìm kiếm quanh trường cần tọa độ đáng tin cậy để đo khoảng cách. Không nên dựa vào tọa độ ước lượng, một ghim không rõ nguồn hoặc tên gọi chung để khẳng định phòng ở gần trường. Khi HOLA Maps chưa có mốc trường đủ điều kiện, trang này tiếp tục là bản nháp, không công bố danh sách địa điểm như thể đã xác minh.","Khi có hồ sơ thuê phù hợp, hãy đối chiếu ảnh với phòng thực tế, kiểm tra điều kiện an toàn và quyền cho thuê trước khi đặt cọc. Báo cáo tin hết phòng hoặc thông tin không còn chính xác để đội ngũ kiểm duyệt cập nhật. Chỉ hiển thị danh sách khi dữ liệu thực tế vượt qua ngưỡng xuất bản và biên tập viên đã kiểm tra."]}]'::jsonb,'DRAFT')
ON CONFLICT (slug) DO NOTHING;
